def clear_legacy_sheet_data(apps, schema_editor):
    """★ 旧答题卡数据不保留（需求已确认）；作业与成绩保留。

    顺序（外键 PROTECT）：
      1. `assignment.sheet_template := NULL`（字段保留、可空）
      2. scan_card → scan_batch → paper_sheet_binding → sheet_template → sheet_style

    ★ 可重复执行：全部是 DELETE/UPDATE，重复跑不会报错。
    ★ 开发库（SQLite）与生产库（PostgreSQL）都只走 ORM，不写方言 SQL。
    """
    Assignment = apps.get_model("assignment", "Assignment")
    Assignment._base_manager.all().filter(
        sheet_template__isnull=False).update(sheet_template=None)

    # ★ org.sheet_default_style 是 PROTECT 外键；不先置空，
    #   删 sheet_style 会抛 ProtectedError，迁移在生产库上直接失败。
    Org = apps.get_model("org", "Org")
    Org._base_manager.all().filter(
        sheet_default_style__isnull=False).update(sheet_default_style=None)

    for app_label, model_name in (
        ("omr", "ScanCard"),
        ("omr", "ScanBatch"),
        ("sheet", "PaperSheetBinding"),
        ("sheet", "SheetTemplate"),
        ("sheet", "SheetStyle"),
    ):
        model = apps.get_model(app_label, model_name)
        # ★ 用 _base_manager：软删模型的默认 manager 会过滤 deleted_at，
        #   迁移清理必须把"已软删的旧卡"也清掉。
        model._base_manager.all().delete()


